-- ═══════════════════════════════════════════════════════════
-- EnglishUp · Seed 02 · 2.801 headword NGSL
-- CHẠY SAU 01_migration.sql
--
-- An toàn: dùng ON CONFLICT — từ đã có trong DB thì CHỈ nạp thêm
-- metadata NGSL (rank/band/track/word_family). Phiên âm, nghĩa,
-- level bạn đã biên tập sẽ KHÔNG bị ghi đè.
-- ═══════════════════════════════════════════════════════════


-- rank 1–400
ON CONFLICT (lower(term)) DO UPDATE SET
  ngsl_rank        = EXCLUDED.ngsl_rank,
  ngsl_band        = EXCLUDED.ngsl_band,
  track            = EXCLUDED.track,
  is_function_word = EXCLUDED.is_function_word,
  word_family      = EXCLUDED.word_family,
  family_size      = EXCLUDED.family_size,
  phonetic         = COALESCE(NULLIF(words.phonetic, ''), EXCLUDED.phonetic),
  definition_vi    = COALESCE(NULLIF(words.definition_vi, ''), EXCLUDED.definition_vi),
  part_of_speech   = COALESCE(NULLIF(words.part_of_speech, ''), EXCLUDED.part_of_speech),
  level            = COALESCE(NULLIF(words.level, ''), EXCLUDED.level);


